post.description:
 Creates a new form submission. It is required to provide the formId for this submission, and it is possible to provide pre-sharing data...

**Example**
```json
{
    "formId": "b98cffcd-4e30-4264-85c4-ac4f912e6a8a",
    "expiration": "2",
    "preSharingFormSubmissionDTO": {
        "structure": {
            "jsonSchema": "{
  "type": "object",
  "properties": {
    "cpf": {
      "type": "string",
      "minLength": 1,
      "title": "CPF"
    },
    "name": {
      "type": "string",
      "title": "Nome"
    }
  },
  "required": ["cpf", "name"]
}",
            "uiSchema": "{
  "cpf": {
    "ui:options": {
      "mask": "999.999.999-99"
    }
  }
}"
        },
        "filledData": "{"cpf":"99999999999","name":"USUÁRIO DE TESTE"}"
    }
}
```
